trait Greeter {
    fn name(&self) -> String;
    fn greet(&self) -> String {
        format!("Hello, {}", self.name())
    }
}

struct A;
struct B;

impl Greeter for A {
    fn name(&self) -> String { "A".to_string() }
}

impl Greeter for B {
    fn name(&self) -> String { "B".to_string() }
    fn greet(&self) -> String { "Yo".to_string() }
}

fn main() {
    println!("{}", A.greet());
    println!("{}", B.greet());
}
